// Step-by-step: rank-nullity (Gauss-Jordan) and the simplex method (tableaus).
#pragma once
#include "simulations4.hpp"

inline void addMatrixSteps2(std::map<std::string, Sim>& m) {
    const std::vector<std::string> R = {"3Blue1Brown: Essence of Linear Algebra|https://www.3blue1brown.com/topics/linear-algebra", "MIT OpenCourseWare 18.06 Linear Algebra|https://ocw.mit.edu/courses/18-06-linear-algebra-spring-2010/", "Paul's Online Math Notes|https://tutorial.math.lamar.edu/", "Khan Academy: Linear Algebra|https://www.khanacademy.org/math/linear-algebra"};
    auto fm = [](double x) { return G(std::fabs(x) < 1e-9 ? 0.0 : x); };
    { Sim sm{"Enter a 3-row matrix A with 4 columns (12 numbers, row by row)", "1, 2, 0, 3, 2, 4, 1, 7, 3, 6, 1, 10", {"Reduce A to reduced row echelon form (Gauss-Jordan)", "Pivot columns = columns of A that are independent: rank = number of pivots", "Free columns give free variables: nullity = number of free columns", "Each free variable gives one basis vector of the null space  Ax = 0", "Rank-Nullity:  rank(A) + nullity(A) = number of columns"}, R, {"Make a 3×4 matrix whose third row is the sum of the first two: the rank drops to 2 and the nullity rises to 2."}, nullptr, nullptr, "", {}};
        sm.runS = [fm](const std::string& in) { D v = nums(in); int rows = 3, cols = 4; double M[3][4] = {}; for (int i = 0; i < rows; ++i) for (int j = 0; j < cols; ++j) { size_t k = i * cols + j; M[i][j] = k < v.size() ? v[k] : 0; } Steps s; auto snap = [&](int line, std::string note, int hi) { Step st = mk(line, note); for (int i = 0; i < rows; ++i) for (int j = 0; j < cols; ++j) st.mat.push_back(fm(M[i][j])); st.mc = cols; st.hi = hi; s.push_back(st); };
            snap(0, "The matrix A (3 rows, 4 columns): this is a map from R⁴ to R³.", -1); int r0 = 0; std::vector<int> piv;
            for (int c = 0; c < cols && r0 < rows; ++c) { int pr = -1; for (int i = r0; i < rows; ++i) if (std::fabs(M[i][c]) > 1e-9) { pr = i; break; } if (pr < 0) { snap(2, "Column " + S(c + 1) + " has no pivot: it is a FREE column.", -1); continue; } if (pr != r0) { for (int j = 0; j < cols; ++j) std::swap(M[r0][j], M[pr][j]); snap(0, "Swap R" + S(r0 + 1) + " and R" + S(pr + 1) + ".", r0 * cols + c); }
                double pv = M[r0][c]; for (int j = 0; j < cols; ++j) M[r0][j] /= pv; snap(0, "Scale R" + S(r0 + 1) + " so the pivot becomes 1 (divide by " + fm(pv) + ").", r0 * cols + c);
                for (int i = 0; i < rows; ++i) if (i != r0 && std::fabs(M[i][c]) > 1e-9) { double f = M[i][c]; for (int j = 0; j < cols; ++j) M[i][j] -= f * M[r0][j]; M[i][c] = 0; snap(0, "R" + S(i + 1) + " → R" + S(i + 1) + " − (" + fm(f) + ")·R" + S(r0 + 1) + " (clear the rest of column " + S(c + 1) + ").", i * cols + c); } piv.push_back(c); ++r0; }
            int rank = piv.size(), nul = cols - rank; std::string ps, fs; for (int c = 0; c < cols; ++c) { bool isP = false; for (int q : piv) if (q == c) isP = true; (isP ? ps : fs) += (std::string(isP ? (ps.empty() ? "" : ", ") : (fs.empty() ? "" : ", ")) + S(c + 1)); }
            snap(1, "Reduced row echelon form. Pivot columns: " + (ps.empty() ? std::string("none") : ps) + ".  rank(A) = " + S(rank) + ".", -1);
            snap(2, "Free columns: " + (fs.empty() ? std::string("none") : fs) + ".  nullity(A) = " + S(nul) + " (the dimension of the null space).", -1);
            for (int c = 0; c < cols; ++c) { bool isP = false; for (int q : piv) if (q == c) isP = true; if (isP) continue; std::vector<double> x(cols, 0); x[c] = 1; for (size_t k = 0; k < piv.size(); ++k) x[piv[k]] = -M[k][c]; std::string xs; for (int j = 0; j < cols; ++j) xs += (j ? ", " : "") + fm(x[j]); snap(3, "Set free variable x" + S(c + 1) + " = 1 and the other free variables 0. Basis vector of the null space: (" + xs + ").", -1); }
            snap(4, "rank + nullity = " + S(rank) + " + " + S(nul) + " = " + S(cols) + " = the number of columns. ✓", -1); return s; };
        m["Rank–Nullity Theorem"] = sm; }
    { Sim sm{"Enter: c₁ c₂, then each constraint as a b r (a·x₁ + b·x₂ ≤ r). 11 numbers = 3 constraints", "3, 5, 1, 0, 4, 0, 2, 12, 3, 2, 18", {"Write the problem in standard form and add a slack variable to each constraint", "Choose the entering column: the most negative number in the bottom row", "Ratio test: the leaving row has the smallest RHS / (positive entry)", "Pivot: scale the pivot row to 1 and clear the rest of the column", "Optimal when the bottom row has no negative numbers"}, R, {"Try the default (3x + 5y: optimum 36 at (2, 6)). Then change c₂ to 1 and watch the path change."}, nullptr, nullptr, "", {}};
        sm.runS = [fm](const std::string& in) { D v = nums(in); if (v.size() < 5) v = {3, 5, 1, 0, 4, 0, 2, 12, 3, 2, 18}; int k = std::min(4, (int)((v.size() - 2) / 3)); if (k < 1) k = 1; int nc = 2 + k + 1; std::vector<std::vector<double>> T(k + 1, std::vector<double>(nc, 0)); for (int i = 0; i < k; ++i) { T[i][0] = v[2 + 3 * i]; T[i][1] = v[3 + 3 * i]; T[i][2 + i] = 1; T[i][nc - 1] = std::max(0.0, v[4 + 3 * i]); } T[k][0] = -v[0]; T[k][1] = -v[1];
            std::vector<std::string> names = {"x₁", "x₂"}; for (int i = 0; i < k; ++i) names.push_back("s" + S(i + 1)); std::vector<int> basis(k); for (int i = 0; i < k; ++i) basis[i] = 2 + i; Steps s; std::string hd = "Columns: "; for (auto& n : names) hd += n + "  "; hd += "| RHS.  Last row = −profit.";
            auto snap = [&](int line, std::string note, int hi) { Step st = mk(line, note + "  " + hd); for (auto& row : T) for (double x : row) st.mat.push_back(fm(x)); st.mc = nc; st.hi = hi; st.cols = nc - 1; s.push_back(st); }; snap(0, "Initial tableau: maximise " + fm(v[0]) + "x₁ + " + fm(v[1]) + "x₂. Slack variables make a starting corner at the origin (x₁ = x₂ = 0).", -1);
            for (int it = 1; it <= 12; ++it) { int ec = -1; double mn = -1e-9; for (int j = 0; j < nc - 1; ++j) if (T[k][j] < mn) { mn = T[k][j]; ec = j; } if (ec < 0) break; int lr = -1; double br = 1e18; for (int i = 0; i < k; ++i) if (T[i][ec] > 1e-9) { double ratio = T[i][nc - 1] / T[i][ec]; if (ratio < br - 1e-12) { br = ratio; lr = i; } }
                if (lr < 0) { snap(2, "Iteration " + S(it) + ": column " + names[ec] + " has no positive entry, so the objective is UNBOUNDED.", -1); return s; }
                snap(1, "Iteration " + S(it) + ": entering variable " + names[ec] + " (most negative in the bottom row: " + fm(T[k][ec]) + ").", k * nc + ec); snap(2, "Ratio test: smallest RHS/entry is " + fm(br) + " in row " + S(lr + 1) + ", so " + names[basis[lr]] + " leaves the basis. Pivot = " + fm(T[lr][ec]) + ".", lr * nc + ec);
                double pv = T[lr][ec]; for (int j = 0; j < nc; ++j) T[lr][j] /= pv; for (int i = 0; i <= k; ++i) if (i != lr && std::fabs(T[i][ec]) > 1e-12) { double f = T[i][ec]; for (int j = 0; j < nc; ++j) T[i][j] -= f * T[lr][j]; } basis[lr] = ec; snap(3, "Pivot done: " + names[ec] + " is now basic in row " + S(lr + 1) + ". Current profit = " + fm(T[k][nc - 1]) + ".", lr * nc + ec); }
            double x1 = 0, x2 = 0; for (int i = 0; i < k; ++i) { if (basis[i] == 0) x1 = T[i][nc - 1]; if (basis[i] == 1) x2 = T[i][nc - 1]; } snap(4, "No negative numbers in the bottom row: OPTIMAL. x₁ = " + fm(x1) + ", x₂ = " + fm(x2) + ", maximum profit = " + fm(T[k][nc - 1]) + ". The bottom row under the slacks gives the dual variables (shadow prices).", -1); return s; };
        m["Linear Programming: Simplex Method"] = sm; }
}
